def zeros4(i,o):
    h,w=len(i),len(i[0])
    res=[]
    for r in range(h):
        for c in range(w):
            if i[r][c]==0:
                n=sum(1 for dr,dc in ((1,0),(-1,0),(0,1),(0,-1))
                      if 0<=r+dr<h and 0<=c+dc<w and i[r+dr][c+dc]==0)
                changed = o[r][c]==8
                res.append((n,changed))
    return res
