# also 8-connectivity variant
def zeros8(i,o):
    h,w=len(i),len(i[0]); bad=0
    for r in range(h):
        for c in range(w):
            if i[r][c]==0:
                n=sum(1 for dr in(-1,0,1) for dc in(-1,0,1) if (dr or dc)
                      and 0<=r+dr<h and 0<=c+dc<w and i[r+dr][c+dc]==0)
                if (n>=1)!=(o[r][c]==8): bad+=1
    return bad
