def f(g):
    h,w=len(g),len(g[0])
    out=[row[:] for row in g]
    for r in range(h):
        for c in range(w):
            if g[r][c]==0 and any(0<=r+dr<h and 0<=c+dc<w and g[r+dr][c+dc]==0
                                  for dr,dc in ((1,0),(-1,0),(0,1),(0,-1))):
                out[r][c]=8
    return out
